      'name: filter-severity-complete\ntype: pipeline\ndescription: Complete Log Severity Filtering Pipeline with JSON parsing, intelligent severity detection, and conditional routing.\nnamespace: production\nlabels:\n  category: log-processing\n  pattern: severity-filtering\n\nconfig:\n  input:\n    file:\n      paths:\n        - /var/log/app/*.log\n      codec: lines\n\n  pipeline:\n    processors:\n      # Stage 1: JSON Parsing with Fallback\n      - mapping: |\n          let original = content().string()\n          let parsed = $original.parse_json().catch(null)\n          let log_match = $original.re_find_all_submatch("(\\\\d{4}-\\\\d{2}-\\\\d{2} \\\\d{2}:\\\\d{2}:\\\\d{2}) \\\\[([A-Z]+)\\\\] (.+)")\n\n          root = if $parsed.type() == "object" {\n            $parsed.merge({"original_format": "json", "parsing_success": true})\n          } else if $log_match.length() > 0 {\n            {\n              "timestamp": $log_match.index(0).index(1),\n              "level": $log_match.index(0).index(2),\n              "message": $log_match.index(0).index(3),\n              "original_format": "structured_text",\n              "parsing_success": true\n            }\n          } else {\n            {\n              "original_message": $original,\n              "level": "UNKNOWN",\n              "original_format": "unstructured_text",\n              "parsing_success": false\n            }\n          }\n\n      # Stage 2: Processing Metadata\n      - mapping: |\n          root = this\n          root.processing_metadata = {\n            "processed_at": now(),\n            "node_id": env("NODE_ID").or("unknown"),\n            "pipeline_version": env("PIPELINE_VERSION").or("1.0")\n          }\n\n      # Stage 3: Severity Detection and Normalization\n      - mapping: |\n          root = this\n          let log_level = this.level.or("UNKNOWN").string().uppercase()\n          let content_lower = (this.message.or("").string() + " " + this.original_message.or("").string()).lowercase()\n\n          let error_keywords = ["error", "fail", "exception", "crash", "critical", "fatal"]\n          let warn_keywords = ["warn", "warning", "alert", "caution", "timeout"]\n\n          let detected_level = if $log_level != "UNKNOWN" {\n            $log_level\n          } else if $error_keywords.any(keyword -> $content_lower.contains(keyword)) {\n            "ERROR"\n          } else if $warn_keywords.any(keyword -> $content_lower.contains(keyword)) {\n            "WARN"\n          } else {\n            "UNKNOWN"\n          }\n\n          let level_mappings = {\n            "FATAL": "ERROR",\n            "SEVERE": "ERROR",\n            "CRITICAL": "ERROR",\n            "WARNING": "WARN"\n          }\n\n          root.level = $level_mappings.get($detected_level).or($detected_level)\n          root.original_level = $log_level\n\n      # Stage 4: Severity-Based Filtering\n      - mapping: |\n          let level = this.level.string().uppercase()\n\n          root = if $level == "ERROR" || $level == "WARN" {\n            this.merge({\n              "filter_metadata": {\n                "passed_filter": true,\n                "filter_reason": "severity_match",\n                "filtering_timestamp": now()\n              }\n            })\n          } else {\n            deleted()\n          }\n\n  output:\n    broker:\n      pattern: fan_out\n      outputs:\n        - switch:\n            cases:\n              - check: this.level == "ERROR"\n                output:\n                  file:\n                    path: /var/log/expanso/errors/${!timestamp_unix_date()}.json\n                    codec: lines\n\n              - check: this.level == "WARN"\n                output:\n                  stdout:\n                    codec: lines\n\n              - output:\n                  file:\n                    path: /var/log/expanso/unrouted-logs.json\n                    codec: lines\n\nlogger:\n  level: INFO\n  format: json\n\nmetrics:\n  prometheus:\n    path: /metrics\n',
